-- 002: plain-language help texts shown as tooltips in the UI.
-- Looked up by key (a control id or a table column name, lower-case). Edit them in the app's
-- Glossary tab or directly in this table; the UI reads them at run time.

CREATE TABLE help_texts (
    key           TEXT PRIMARY KEY,              -- control id or column name, lower-case
    term          TEXT NOT NULL,                 -- display name in the glossary
    category      TEXT NOT NULL,                 -- app | market | astrology | statistics | model
    description   TEXT NOT NULL,                 -- Markdown
    updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now'))
);

INSERT INTO help_texts(key, term, category, description) VALUES
('search_symbol', 'Search symbol', 'app', 'Start typing a company name or ticker code. Up to 5 suggestions appear from symbols you have used before and from the market data provider.'),
('stock_index', 'Stock / index', 'market', 'The stock or market index to analyse. An index (for example Nifty 50 or S&P 500) tracks a basket of stocks. Symbols that start with ^ are indices.'),
('symbol', 'Symbol (ticker)', 'market', 'Short code that identifies a stock on Yahoo Finance. Indian stocks end in .NS (NSE) or .BO (BSE), London stocks in .L, US stocks have no suffix. Examples: RELIANCE.NS, AAPL, ^NSEI.'),
('exchange', 'Exchange', 'market', 'The stock exchange where this instrument trades. It decides trading hours, holidays, time zone and currency. It is detected from the symbol; change it only if the guess is wrong.'),
('display_timezone', 'Display timezone', 'app', 'Time zone used to show times on screen. It does not change any calculation.'),
('astro_system', 'Astrological system', 'astrology', 'Vedic (sidereal) measures planet positions against the fixed stars, as in Indian Jyotish. Western (tropical) measures them against the seasons, so the Sun enters Aries at the March equinox. The two differ by about 24 degrees, so a planet''s sign can differ between systems.'),
('ayanamsa', 'Ayanamsa', 'astrology', 'The correction (about 24 degrees today) that converts Western positions to Vedic ones. Different traditions use slightly different values; Lahiri is the Indian government standard and the usual choice. Only used in the Vedic system.'),
('lunar_node', 'Lunar node (Rahu/Ketu)', 'astrology', 'Rahu and Ketu are the two points where the Moon''s path crosses the Sun''s path; eclipses happen near them. ''Mean'' uses a smoothed average position (traditional); ''true'' uses the exact wobbling position.'),
('aspect_orb', 'Aspect orb', 'astrology', 'How close (in degrees) two planets must be to an exact angle to count as an aspect. A smaller orb counts only tight aspects; a larger orb counts more, looser ones.'),
('period', 'Period', 'app', 'How much price history the chart shows. 1D and 5D use intraday (minute-level) prices; the others use one price per day.'),
('bars', 'Bars', 'market', 'How prices are grouped on the chart: one bar per day, week, month or year. Each bar shows open, high, low and close for that period.'),
('latest_price', 'Latest price', 'market', 'Most recent traded price and its change since the previous close. Free data feeds are usually delayed by up to about 15 minutes; the badge shows how fresh it is.'),
('sky_now', 'Sky now', 'astrology', 'Where the Sun, Moon and planets are at this moment, shown both as measured astronomy and as astrological labels (sign, nakshatra).'),
('upcoming_events', 'Upcoming astrological events', 'astrology', 'Planet sign changes, retrograde stations, new/full moons and exact aspects expected in the next 30 days, calculated from the planetary ephemeris.'),
('moon_phase', 'Moon phase', 'astrology', 'Shape of the Moon as seen from Earth (new, waxing, full, waning), with the percentage of its face lit by the Sun.'),
('tithi', 'Tithi', 'astrology', 'Vedic lunar day. Each tithi is a 12-degree step of the Moon ahead of the Sun, giving 30 tithis per lunar month (15 waxing, 15 waning).'),
('paksha', 'Paksha', 'astrology', 'Half of the lunar month: Shukla paksha is the waxing (brightening) half, Krishna paksha the waning (darkening) half.'),
('moon_sign', 'Moon sign', 'astrology', 'The zodiac sign (one of 12 slices of 30 degrees) the Moon is in. The Moon changes sign about every 2.5 days.'),
('moon_nakshatra', 'Moon nakshatra', 'astrology', 'Vedic lunar mansion: the zodiac split into 27 parts of 13 degrees 20 minutes. The Moon passes through about one nakshatra per day.'),
('astronomical_positions', 'Astronomical positions', 'astrology', 'Measured, physical quantities: where each body is in the sky, how far away and how fast it moves. These are facts, independent of any astrological tradition.'),
('astrological_interpretation', 'Astrological interpretation', 'astrology', 'Labels that astrological traditions put on the measured positions (sign, nakshatra, retrograde). These are conventions, not measurements.'),
('date_range', 'Date range', 'app', 'Period of price history to show and analyse.'),
('forward_return_sessions', 'Forward return (sessions)', 'statistics', 'How many trading days ahead to measure the price change after each day. For example 5 means: if you bought at that day''s close, what was the return 5 trading days later.'),
('highlight_condition', 'Highlight condition', 'astrology', 'Shade the price chart on days when the chosen astrological condition was true (for example Mercury retrograde), so you can compare by eye.'),
('observed_correlations', 'Observed correlations', 'statistics', 'For every astrological condition, compares the average future return on days when it was true against all other days. Testing many conditions produces some ''significant'' results by pure luck, so look at the FDR-corrected column.'),
('event_study', 'Event study', 'statistics', 'Average price path in the days before and after an astrological event, compared with the stock''s normal drift. The shaded band is the 95% confidence range; if it includes the normal drift line, the effect may be chance.'),
('event', 'Event', 'astrology', 'Type of astrological event to study. Only events that happened at least 8 times in the price history are listed.'),
('as_of', 'As-of session', 'app', 'The date the forecast is made from. Pick a past date to replay a forecast exactly as it could have been made then: only prices up to that day''s close are used.'),
('target', 'Target', 'app', 'What to forecast: the next few trading days, one specific date, or a date range.'),
('target_sessions', 'Sessions', 'market', 'Number of trading days (sessions) ahead to forecast. Weekends and exchange holidays are skipped.'),
('target_date', 'Target date', 'app', 'The calendar date to forecast. If it is a weekend or holiday, the next trading day is used.'),
('target_range', 'Target range', 'app', 'Start and end dates of the forecast window. The forecast is the total return over the trading days in this range.'),
('headline_model', 'Headline model', 'model', 'The model whose result is shown as the main forecast. All selected models are still listed in the comparison table.'),
('models', 'Models', 'model', 'Each model gives the chance the price goes up and an expected return; they differ only in the data they use.

- **Naive: no change**: always 50% / 0% return (pure guessing).
- **Naive: historical average**: past share of up-days and average return. Hard to beat, since markets drift up.
- **Market-only**: past returns, volatility, volume, technical indicators. No astrology.
- **Astro-only (Model A, L1)**: planetary features only; keeps just the astro features with signal. Tests whether astrology predicts anything on its own.
- **Hybrid (Model C)**: market + astro features. Tests whether astrology adds value beyond market data.

*Linear* = simple, constrained, interpretable. *LightGBM / XGBoost* = boosted trees; capture complex patterns but overfit more easily.

**Reading results:** Astro-only should beat Naive, and Hybrid should beat Market-only, on the same out-of-sample dates; otherwise astrology adds nothing here.'),
('direction', 'Direction', 'model', 'Bullish = the model expects the price to rise, bearish = to fall, neutral = too close to 50/50 to call. P(up) is the model''s probability that the price ends the window higher.'),
('expected_return', 'Expected return', 'model', 'The model''s best estimate of the percentage price change over the window. The 80% interval is the range the actual result fell into 8 times out of 10 in past testing.'),
('expected_volatility', 'Expected volatility', 'market', 'How much the price typically swings over a window of this length, based on recent daily movements. Higher volatility means higher risk. The risk label compares it with this stock''s own history.'),
('validated_hit_rate', 'Validated hit rate', 'statistics', 'How often this model got the direction right when tested on past data it had not seen. The 95% CI is the range the true hit rate probably lies in; n is the number of tests.'),
('confidence', 'Confidence', 'statistics', 'How reliable the model''s probability is, measured on past out-of-sample tests. ''Not calibrated'' means there was too little evidence to say.'),
('evidence_badge', 'Evidence', 'statistics', 'Validated = the model beat the naive baseline on unseen data with statistical significance. Experimental = no proven edge; treat the forecast as noise. Insufficient = too little data to test.'),
('predicted_price', 'Predicted price', 'model', 'The expected return converted into a price level, starting from the as-of close. The shaded band is the 80% range.'),
('as_of_close', 'As-of close', 'market', 'Closing price on the day the forecast was made from.'),
('expected_close', 'Expected close', 'model', 'Price implied by the expected return at the end of the forecast window.'),
('price_range_80', '80% price range', 'statistics', 'In past testing, the actual price ended inside a range like this about 8 times out of 10.'),
('all_models', 'All models for this target', 'model', 'Every selected model''s forecast for the same window, with how well each did in past out-of-sample testing.'),
('window_conditions', 'Astrological conditions during the window', 'astrology', 'Planet signs, lunar day, retrogrades and aspects on each trading day of the forecast window.'),
('analogues', 'Historical analogues', 'statistics', 'Past days when the fast-moving planets (Sun, Moon, Mercury, Venus, Mars) were in similar positions, and what the stock did afterwards. Matching the Sun also matches the time of year, so seasonality can explain any pattern.'),
('analogue_sessions', 'Analogue sessions', 'statistics', 'Number of past trading days with a similar sky.'),
('analogue_mean_return', 'Mean return (analogues)', 'statistics', 'Average return after those similar-sky days, compared with the average after all days.'),
('analogue_up_share', 'Up share (analogues)', 'statistics', 'Share of similar-sky days that were followed by a price rise, compared with all days.'),
('timeline_range', 'Range', 'app', 'Dates to plot planet positions for. Future dates are calculated from the ephemeris (planetary tables).'),
('bodies', 'Bodies', 'astrology', 'Sun, Moon, planets and lunar nodes to plot. Each point is the body''s position around the zodiac (0-360 degrees, 30 degrees per sign).'),
('event_types', 'Event types', 'astrology', '**ingress**: a planet enters a new sign. **station_retrograde / station_direct**: a planet appears to stop and reverse direction (retrograde = apparent backward motion). **new_moon / full_moon**: Moon conjunct / opposite the Sun. **eclipse_season**: new or full moon close to the lunar nodes. **exact_conjunction / sextile / square / trine / opposition**: two planets exactly 0, 60, 90, 120 or 180 degrees apart.'),
('horizon', 'Horizon (sessions)', 'statistics', 'How many trading days ahead each tested forecast looks.'),
('gap', 'Gap (sessions)', 'statistics', 'Trading days skipped between the forecast date and the start of the window. 0 means the window starts the next trading day.'),
('permutations', 'Permutations', 'statistics', 'Extra check for Model A: astrology data is shuffled many times to see how often chance alone matches the real result. More permutations = more reliable but slower. 0 skips it.'),
('astro_value', 'Does astrology add predictive value?', 'statistics', 'Each astro or hybrid model is compared on the same dates with a model that has no astrology. A difference counts only if its p-value is below 0.05.'),
('strategy_simulation', 'Strategy simulation', 'statistics', 'What would have happened to 1 unit of money if you had followed each model: invested when it predicted up, in cash otherwise, including trading costs. Simulation only; past results do not guarantee future ones.'),
('predicted_vs_actual', 'Predicted vs actual', 'statistics', 'Each dot is one past test: predicted return vs what actually happened. A model with skill shows dots sloping upward; a round blob means no relationship.'),
('stored_backtests', 'Stored backtest runs', 'app', 'Results of earlier backtests saved in the database.'),
('stored_forecasts', 'Stored forecasts', 'app', 'Forecasts saved in the database, with the actual return filled in once the window has passed.'),
('update_realised', 'Update realised returns', 'app', 'Fill in the actual returns for saved forecasts whose window has now passed.'),
('model_comparison', 'Model comparison', 'statistics', 'Every model tested walk-forward on identical past dates: trained only on data before each test period, then scored on the period it did not see.'),
('body', 'Body', 'astrology', 'Sun, Moon, planet or lunar node (Rahu/Ketu).'),
('longitude', 'Longitude', 'astrology', 'Position around the zodiac in degrees (0-360). Every 30 degrees is one sign.'),
('latitude', 'Latitude', 'astrology', 'Degrees above or below the Sun''s apparent path (the ecliptic).'),
('distance_au', 'Distance (AU)', 'astrology', 'Distance from Earth in astronomical units (1 AU = average Earth-Sun distance, about 150 million km).'),
('speed_deg_day', 'Speed (deg/day)', 'astrology', 'How many degrees the body moves along the zodiac per day. Negative speed means it is retrograde.'),
('declination', 'Declination', 'astrology', 'Angle north (+) or south (-) of the celestial equator.'),
('sign', 'Sign', 'astrology', 'Zodiac sign (Rashi in Vedic): one of 12 equal 30-degree slices of the zodiac.'),
('degree_in_sign', 'Degree in sign', 'astrology', 'How far into its sign the body is (0-30 degrees).'),
('nakshatra', 'Nakshatra', 'astrology', 'Vedic lunar mansion: one of 27 slices of 13 degrees 20 minutes.'),
('pada', 'Pada', 'astrology', 'Quarter of a nakshatra (1-4), each 3 degrees 20 minutes.'),
('retrograde', 'Retrograde', 'astrology', 'The planet appears to move backwards through the zodiac, an optical effect of Earth overtaking it (or it overtaking Earth).'),
('aspect', 'Aspect', 'astrology', 'Angle between two bodies: conjunction 0, sextile 60, square 90, trine 120, opposition 180 degrees.'),
('orb', 'Orb', 'astrology', 'How many degrees the aspect is from exact.'),
('applying', 'Applying', 'astrology', 'True if the aspect is getting tighter (moving towards exact), false if separating.'),
('event_type', 'Event type', 'astrology', 'Kind of astrological event (ingress, station, new/full moon, eclipse season, exact aspect).'),
('detail', 'Detail', 'astrology', 'Description of the event: which bodies and signs are involved.'),
('major_aspects', 'Major aspects', 'astrology', 'Aspects between planets in effect on that day.'),
('condition', 'Condition', 'astrology', 'Astrological state tested, for example ''Moon sign'' or ''Mercury retrograde''.'),
('value', 'Value', 'astrology', 'The specific value of the condition (for example ''Aries'', or ''yes'').'),
('open', 'Open', 'market', 'First traded price of the session.'),
('high', 'High', 'market', 'Highest traded price of the session.'),
('low', 'Low', 'market', 'Lowest traded price of the session.'),
('close', 'Close', 'market', 'Last traded price of the session; most analysis uses this.'),
('adj_close', 'Adjusted close', 'market', 'Close price adjusted for dividends and stock splits, so returns over time are comparable.'),
('volume', 'Volume', 'market', 'Number of shares (or contracts) traded during the session.'),
('pct_change', '% change', 'market', 'Price change from the previous session''s close.'),
('ts_utc', 'Timestamp (UTC)', 'app', 'Exact moment in Coordinated Universal Time (UTC), the world reference clock.'),
('sessions', 'Sessions', 'market', 'Number of trading days in the sample.'),
('mean_bps', 'Mean (bps)', 'statistics', 'Average forward return when the condition was true, in basis points (1 bp = 0.01%, so 100 bps = 1%).'),
('rest_mean_bps', 'Rest mean (bps)', 'statistics', 'Average forward return on all other days, in basis points, for comparison.'),
('vol_bps', 'Volatility (bps)', 'statistics', 'Typical size of the return swings when the condition was true (standard deviation), in basis points.'),
('hit_rate', 'Hit rate', 'statistics', 'Share of cases where the return was positive (or the prediction was right).'),
('t_stat', 't-statistic', 'statistics', 'How many standard errors the difference is from zero. Roughly, values beyond +/-2 are unusual for pure chance.'),
('p_value', 'p-value', 'statistics', 'Probability of seeing a difference at least this big if there were no real effect. Small (below 0.05) suggests a real effect, but with many tests some will be small by luck.'),
('q_value', 'q-value', 'statistics', 'p-value adjusted for testing many conditions at once (Benjamini-Hochberg). Use this rather than the raw p-value.'),
('significant_fdr', 'Significant (FDR)', 'statistics', 'True if the result is still significant after correcting for the number of conditions tested (false discovery rate).'),
('accuracy', 'Accuracy', 'statistics', 'Share of tests where the model called the direction (up/down) correctly. Compare with the share of up-windows: always guessing ''up'' can already score well.'),
('precision', 'Precision', 'statistics', 'When the model said ''up'', how often the price actually went up.'),
('recall', 'Recall', 'statistics', 'Of all the windows that went up, how many the model correctly called ''up''.'),
('f1', 'F1 score', 'statistics', 'Balance of precision and recall in one number (0-1, higher is better).'),
('auc', 'AUC', 'statistics', 'How well the model ranks up-windows above down-windows (0.5 = coin flip, 1.0 = perfect). For markets, anything consistently above 0.52 is notable.'),
('brier', 'Brier score', 'statistics', 'Accuracy of the predicted probabilities (0 = perfect, 0.25 = always saying 50%). Lower is better.'),
('mae', 'MAE', 'statistics', 'Mean absolute error: average size of the miss between predicted and actual return. Lower is better.'),
('rmse', 'RMSE', 'statistics', 'Root mean squared error: like MAE but punishes big misses more. Lower is better.'),
('r2_vs_zero', 'R2 vs zero', 'statistics', 'How much better the return predictions are than always predicting 0%. Above 0 = better, below 0 = worse.'),
('edge_p_value', 'Edge p-value', 'statistics', 'Probability the model''s accuracy edge over the naive baseline is just luck. Below 0.05 counts as a validated edge.'),
('n', 'n', 'statistics', 'Number of predictions tested.'),
('n_independent', 'Independent windows', 'statistics', 'Number of non-overlapping windows. Overlapping windows share days, so only these count as independent evidence.'),
('evidence', 'Evidence', 'statistics', 'Validated = beat the naive baseline significantly on unseen data. Experimental = no proven edge. Insufficient = too little data. Baseline = a naive reference model.'),
('family', 'Family', 'model', 'Model group: baseline (naive), market (no astrology), astro (astrology only) or hybrid (both).'),
('model', 'Model', 'model', 'Name of the forecasting model.'),
('version', 'Version', 'model', 'Code and settings fingerprint of the model, so stored results can be traced exactly.'),
('base_up_rate', 'Base up rate', 'statistics', 'Share of all test windows in which the price went up.'),
('majority_rate', 'Majority rate', 'statistics', 'Accuracy you would get by always predicting the most common direction. A model must beat this to be useful.'),
('accuracy_independent', 'Accuracy (independent)', 'statistics', 'Accuracy measured on non-overlapping windows only.'),
('eval_start', 'Evaluation start', 'statistics', 'First date of the out-of-sample test period.'),
('eval_end', 'Evaluation end', 'statistics', 'Last date of the out-of-sample test period.'),
('folds', 'Folds', 'statistics', 'Number of consecutive test periods in the walk-forward evaluation.'),
('cost_bps', 'Cost (bps)', 'market', 'Trading cost assumed per position change, in basis points (1 bp = 0.01%).'),
('vs', 'Compared with', 'statistics', 'The non-astrology model used as the comparison.'),
('accuracy_diff', 'Accuracy difference', 'statistics', 'Accuracy of this model minus the comparison model. Positive = better.'),
('auc_diff', 'AUC difference', 'statistics', 'AUC of this model minus the comparison model. Positive = better.'),
('mcnemar_p', 'McNemar p', 'statistics', 'p-value of the McNemar test, which checks whether the two models'' direction accuracy really differs. Below 0.05 = significant.'),
('rmse_diff', 'RMSE difference', 'statistics', 'RMSE of this model minus the comparison model. Negative = smaller errors (better).'),
('sq_error_p', 'Squared-error p', 'statistics', 'p-value for whether the difference in return-prediction errors is real. Below 0.05 = significant.'),
('cagr', 'CAGR', 'statistics', 'Compound annual growth rate: the average yearly return of the simulated strategy.'),
('sharpe', 'Sharpe ratio', 'statistics', 'Return per unit of risk (volatility), per year. Above 1 is good; buy & hold of an index is often 0.3-0.6.'),
('max_drawdown', 'Max drawdown', 'statistics', 'Largest fall from a previous peak, i.e. the worst loss an investor would have sat through.'),
('final_multiple', 'Final multiple', 'statistics', 'What 1 unit of money grew to by the end (2.0 = doubled).'),
('trades', 'Trades', 'statistics', 'Number of times the strategy switched between invested and cash.'),
('time_in_market', 'Time in market', 'statistics', 'Share of the time the strategy was invested.'),
('distance', 'Distance', 'statistics', 'How different that day''s sky was from the target sky (smaller = more similar).'),
('forward_return', 'Forward return', 'statistics', 'Price change over the following window after that day.'),
('p(up)', 'P(up)', 'model', 'Model''s probability that the price ends the window higher.'),
('prob_up', 'P(up)', 'model', 'Model''s probability that the price ends the window higher.'),
('expected', 'Expected', 'model', 'Expected percentage return over the window.'),
('low 80%', 'Low 80%', 'statistics', 'Lower end of the 80% range for the return.'),
