('interval_low', 'Interval low', 'statistics', 'Lower end of the 80% range for the return (log return).'),
('interval_high', 'Interval high', 'statistics', 'Upper end of the 80% range for the return (log return).'),
('expected price', 'Expected price', 'model', 'Price implied by the expected return.'),
('price low 80%', 'Price low 80%', 'statistics', 'Lower end of the 80% price range.'),
