('val. accuracy', 'Validation accuracy', 'statistics', 'Direction accuracy of this model in past out-of-sample testing.'),
('val. auc', 'Validation AUC', 'statistics', 'AUC of this model in past out-of-sample testing (0.5 = coin flip).'),
('edge p', 'Edge p-value', 'statistics', 'Probability the model''s edge over the naive baseline is luck. Below 0.05 = validated.'),
('as_of_session', 'As-of session', 'app', 'Trading day the forecast was made from.'),
('window_start', 'Window start', 'app', 'First trading day of the forecast window.'),
('window_end', 'Window end', 'app', 'Last trading day of the forecast window.'),
('horizon_sessions', 'Horizon (sessions)', 'statistics', 'Length of the forecast window in trading days.'),
('gap_sessions', 'Gap (sessions)', 'statistics', 'Trading days skipped before the window starts.'),
('zodiac', 'Zodiac', 'astrology', 'sidereal = Vedic, tropical = Western.'),
('risk_category', 'Risk category', 'market', 'Expected volatility compared with this stock''s own history (low / medium / high).'),
('realized_return', 'Realised return', 'statistics', 'What the price actually did over the window, once it has passed.'),
